def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    # Read contiguous non-background bars along the four borders.
    edge_runs = {name: [] for name in ("top", "bottom", "left", "right")}
    edges = [
        ("top", [grid[0][c] for c in range(w)]),
        ("bottom", [grid[h - 1][c] for c in range(w)]),
        ("left", [grid[r][0] for r in range(h)]),
        ("right", [grid[r][w - 1] for r in range(h)]),
    ]
    for name, values in edges:
        i = 0
        while i < len(values):
            j = i + 1
            while j < len(values) and values[j] == values[i]:
                j += 1
            if values[i] != background and j - i >= 2:
                edge_runs[name].append((i, j - i, values[i]))
            i = j

    # Opposite matching bars are a pair of guides. Objects aligned with a
    # guide offset activate rays from both corresponding border positions.
    pairs = []
    for first, second, orientation in (("top", "bottom", "vertical"),
                                       ("left", "right", "horizontal")):
        for a in edge_runs[first]:
            for b in edge_runs[second]:
                if a[1:] == b[1:]:
                    pairs.append((first, a, second, b, orientation))

    result = [row[:] for row in grid]
    for edge_a, run_a, edge_b, run_b, orientation in pairs:
        start_a, length, _ = run_a
        start_b = run_b[0]
        marker_cells = set()
        if orientation == "vertical":
            for k in range(length):
                marker_cells.add((0, start_a + k))
                marker_cells.add((h - 1, start_b + k))
        else:
            for k in range(length):
                marker_cells.add((start_a + k, 0))
                marker_cells.add((start_b + k, w - 1))

        for offset in range(length):
            if orientation == "vertical":
                col_a, col_b = start_a + offset, start_b + offset
                line = [(r, col_a) for r in range(h)] + [(r, col_b) for r in range(h)]
            else:
                row_a, row_b = start_a + offset, start_b + offset
                line = [(row_a, c) for c in range(w)] + [(row_b, c) for c in range(w)]

            objects = [(r, c) for r, c in line
                       if grid[r][c] != background and (r, c) not in marker_cells]
            if not objects:
                continue
            ink = grid[objects[0][0]][objects[0][1]]

            for edge, start in ((edge_a, start_a), (edge_b, start_b)):
                position = start + offset
                if orientation == "vertical":
                    if edge == "top":
                        ray = ((r, position) for r in range(1, h))
                    else:
                        ray = ((r, position) for r in range(h - 2, -1, -1))
                else:
                    if edge == "left":
                        ray = ((position, c) for c in range(1, w))
                    else:
                        ray = ((position, c) for c in range(w - 2, -1, -1))

                for r, c in ray:
                    value = grid[r][c]
                    if value != background:
                        if (r, c) not in marker_cells:
                            result[r][c] = 4
                        break
                    result[r][c] = ink
    return result
